import Fastify from 'fastify';

const fastify = Fastify()

fastify.setErrorHandler(async function(error, req, res) {
  const { validation: validations, serialization } = error
  if(validations) {
    // handle ajv error
    return res.code(500).send({
      ok: false,
      data: { token: null },
      message: error.message
    })
  }

  if(serialization) {
    // handle fjs error
    return res.code(500).send({
      data: { token: null },
      message: error.message
    })
  }

  // handle unexpected error
  return res.code(500).send({
    ok: false,
    data: { token: null },
    message: "test",
  })
})

